50: export const GATE_STATUSES = Object.freeze(['COMPLETED', 'NEEDS_REVIEW', 'FAILED']);
51: export const WAITING_REASONS = Object.freeze(['supervisor_review', 'external_dependency']);
52: 
53: /** Single source of truth for the locked bijection; hearth_outcome is always derived from this, never set independently. */
54: const HEARTH_OUTCOME_BY_GATE_STATUS = Object.freeze({
55:   COMPLETED: 'completed',
56:   NEEDS_REVIEW: 'waiting',
57:   FAILED: 'error',
58: });
59: 
60: // Phase 5B safety-boundary codes: the model attempted an out-of-bounds
61: // write and Phase 5B refused it before any mutation. Explicit supervisor
62: // visibility rather than a generic structural FAILED.
63: const SAFETY_BOUNDARY_CODES = Object.freeze(new Set(['PROTECTED_PATH', 'SYMLINK_ESCAPE']));
64: 
65: // Deterministic, objective, not model-retryable structural/authorization/
66: // schema failures. reason_code is the code itself -- these are already
67: // stable, documented identifiers from Phase 5B/6 (see FAILURE_CLASSIFICATION
68: // in repair-loop.mjs), not re-bucketed under a synthetic name.
69: const KNOWN_FAILED_EXECUTION_CODES = Object.freeze(new Set([
70:   'PATH_REJECTED',
71:   'INVALID_SCOPE',
72:   'WRITE_FAILED',
73:   'UNREADABLE_TARGET',
74:   'context_load_failed',
75:   'schema_invalid',
76:   'unsupported_action',
77:   'missing_field',
78:   'too_many_actions',
79:   'too_many_files',
80: ]));
81: 
82: // For the ten deterministic structural execution failures above, we now
83: // normalize reason_code to a single stable identifier instead of passing
84: // the raw blocker code through. This prevents taxonomy churn when lower-
85: // level identifiers change.
86: const STRUCTURAL_EXECUTION_FAILURE_REASON = 'structural_execution_failure';
87: 
88: const buildGateResult = (gateStatus, reasonCode, evidence, waitingReason = null) => {
89:   const hearthOutcome = HEARTH_OUTCOME_BY_GATE_STATUS[gateStatus];
90:   return Object.freeze({
91:     gate_status: gateStatus,
92:     hearth_outcome: hearthOutcome,
93:     reason_code: reasonCode,
94:     waiting_reason: hearthOutcome === 'waiting' ? waitingReason : null,
95:     evidence: Object.freeze(evidence),
96:   });
97: };
