99: /** Structural precondition check. A malformed RepairOutcome is a caller contract violation, not a gate outcome -- fails loudly, matching repair-loop.mjs's own style. */
100: function assertRepairOutcomeShape(repairOutcome) {
101:   if (!repairOutcome || typeof repairOutcome !== 'object') {
102:     throw new TypeError('evaluateResultGate: repairOutcome must be an object');
103:   }
104:   if (repairOutcome.status !== 'validated' && repairOutcome.status !== 'escalation_required') {
105:     throw new TypeError("evaluateResultGate: repairOutcome.status must be 'validated' or 'escalation_required'");
106:   }
107:   if (!Array.isArray(repairOutcome.rounds)) {
108:     throw new TypeError('evaluateResultGate: repairOutcome.rounds must be an array');
109:   }
110:   if (!Array.isArray(repairOutcome.blockers)) {
111:     throw new TypeError('evaluateResultGate: repairOutcome.blockers must be an array');
112:   }
113: }
114: 
115: /** Same key derivation classifyExecutorFailure (repair-loop.mjs) uses: the specific code wins over the generic reason when both are present. */
116: const blockerKeyOf = (blocker) => blocker?.code ?? blocker?.reason ?? null;
117: 
118: const baseEvidence = (repairOutcome, extra = {}) => ({
119:   task_id: repairOutcome.task_id ?? null,
120:   total_rounds: repairOutcome.total_rounds,
121:   ...extra,
122: });
123: 
124: /**
125:  * `status: 'validated'` is Phase 7's own claim; this independently checks
126:  * the evidence actually backs it up before Phase 8 ever reports COMPLETED.
127:  * Required: no top-level blockers, at least one round, a final round of
128:  * kind 'validation' whose `validation.required` is an array every entry of
129:  * which actually reports `status: 'passed'` (an empty required array is
130:  * valid evidence -- vacuously "every result passed" -- since a task may
131:  * legitimately declare no required validation). Any mismatch means the
132:  * RepairOutcome is structurally valid but internally inconsistent -- never
133:  * silently promoted to COMPLETED.
134:  */
135: function hasConsistentCompletionEvidence(repairOutcome) {
136:   if (repairOutcome.blockers.length !== 0) return false;
137:   const lastRound = repairOutcome.rounds[repairOutcome.rounds.length - 1] ?? null;
138:   if (!lastRound || lastRound.kind !== 'validation') return false;
139:   const required = lastRound.validation?.required;
140:   if (!Array.isArray(required)) return false;
141:   return required.every((result) => result?.status === 'passed');
142: }
143: 
144: /**
145:  * Classifies the final execution-kind round of an escalated RepairOutcome.
146:  * `round.classification` is already 'escalate' or 'repairable' (computed by
147:  * Phase 7); this only reads the underlying blocker code to decide which
148:  * NEEDS_REVIEW/FAILED bucket applies, and to fail closed on anything Phase 8
149:  * does not itself recognize.
150:  */
151: function classifyExecutionRound(repairOutcome, round) {
152:   const blocker = round.executor?.blockers?.[0] ?? null;
153:   const key = blockerKeyOf(blocker);
154:   const evidence = baseEvidence(repairOutcome, {
155:     last_round_kind: 'execution',
156:     last_round_classification: round.classification,
157:     blocker: blocker ? Object.freeze({ code: blocker.code ?? null, reason: blocker.reason ?? null, detail: blocker.detail ?? null }) : null,
158:   });
