160:   if (round.classification === 'escalate') {
161:     if (SAFETY_BOUNDARY_CODES.has(key)) {
162:       return buildGateResult('NEEDS_REVIEW', 'safety_boundary_review', evidence, 'supervisor_review');
163:     }
164:     if (KNOWN_FAILED_EXECUTION_CODES.has(key)) {
165:       return buildGateResult('FAILED', STRUCTURAL_EXECUTION_FAILURE_REASON, evidence);
166:     }
167:     return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', evidence, 'supervisor_review');
168:   }
