170:   if (round.classification === 'repairable') {
171:     // Only reachable when the repair budget is exhausted (repair-loop.mjs
172:     // only escalates a 'repairable' round on its final allowed round).
173:     if (key === 'model_request_failed') {
174:       return buildGateResult('NEEDS_REVIEW', 'model_unavailable_after_repair', evidence, 'external_dependency');
175:     }
176:     return buildGateResult('NEEDS_REVIEW', 'repair_budget_exhausted_transient', evidence, 'supervisor_review');
177:   }
178: 
179:   // Unexpected classification value on an execution round of an escalated
180:   // outcome -- Phase 7 never produces this today. Fail closed.
181:   return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', evidence, 'supervisor_review');
