184: /**
185:  * Classifies the final validation-kind round of an escalated RepairOutcome.
186:  * The only validation-side escalation this module expects here is a
187:  * required-validation failure that survived the full repair budget --
188:  * invalid_command escalations are already caught via top-level `blockers`
189:  * before this function is ever reached.
190:  */
191: function classifyValidationRound(repairOutcome, round) {
192:   const evidence = baseEvidence(repairOutcome, {
193:     last_round_kind: 'validation',
194:     last_round_classification: round.classification,
195:     required_validation: (round.validation?.required ?? []).map((r) => ({ command: r.command, status: r.status })),
196:   });
197: 
198:   if (round.classification === 'repairable') {
199:     // Required-validation-failed-after-repair-exhaustion: Phase 7 carries
200:     // no failure_origin evidence, so this can never be asserted as FAILED
201:     // (that would blame X's change without proof). See module docstring.
202:     return buildGateResult('NEEDS_REVIEW', 'repair_budget_exhausted_transient', evidence, 'supervisor_review');
203:   }
