205:   // classification 'escalate' (invalid_command) is handled via top-level
206:   // blockers before reaching here; any other value is unexpected. Fail closed.
207:   return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', evidence, 'supervisor_review');
208: }
