210: /**
211:  * Reduces a Phase 7 `RepairOutcome` to a deterministic Result Gate decision.
212:  *
213:  * @param {object} repairOutcome the frozen object returned by `runTaskWithRepair`
214:  * @returns {{gate_status: 'COMPLETED'|'NEEDS_REVIEW'|'FAILED', hearth_outcome: 'completed'|'waiting'|'error', reason_code: string, waiting_reason: 'supervisor_review'|'external_dependency'|null, evidence: object}}
215:  */
216: export function evaluateResultGate(repairOutcome) {
217:   assertRepairOutcomeShape(repairOutcome);
218: 
219:   if (repairOutcome.status === 'validated') {
220:     if (hasConsistentCompletionEvidence(repairOutcome)) {
221:       const lastRound = repairOutcome.rounds[repairOutcome.rounds.length - 1];
222:       const evidence = baseEvidence(repairOutcome, {
223:         last_round_kind: 'validation',
224:         required_validation: lastRound.validation.required.map((r) => ({ command: r.command, status: r.status })),
225:       });
226:       return buildGateResult('COMPLETED', 'validated', evidence);
227:     }
228:     // status claims 'validated' but the evidence backing that claim is
229:     // missing or contradictory (e.g. a failed/timed-out required result, a
230:     // non-validation final round, zero rounds, or a stray top-level
231:     // blocker). Fail closed to supervisor review rather than throw -- the
232:     // object itself is structurally valid, only internally inconsistent.
233:     const lastRound = repairOutcome.rounds[repairOutcome.rounds.length - 1] ?? null;
234:     const evidence = baseEvidence(repairOutcome, {
235:       last_round_kind: lastRound?.kind ?? null,
236:       top_level_blockers: repairOutcome.blockers.length,
237:       required_validation: Array.isArray(lastRound?.validation?.required)
238:         ? lastRound.validation.required.map((r) => ({ command: r.command, status: r.status }))
239:         : null,
240:     });
241:     return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', evidence, 'supervisor_review');
242:   }
243: 
244:   // status === 'escalation_required' from here on.
245:   const topBlocker = repairOutcome.blockers[0] ?? null;
246:   if (topBlocker?.reason === 'invalid_task_scope' || topBlocker?.reason === 'invalid_validation_command') {
247:     const evidence = baseEvidence(repairOutcome, {
248:       top_level_blocker: Object.freeze({ reason: topBlocker.reason, detail: topBlocker.detail ?? null }),
249:     });
250:     return buildGateResult('FAILED', STRUCTURAL_EXECUTION_FAILURE_REASON, evidence);
251:   }
252:   if (repairOutcome.blockers.length > 0) {
253:     // A top-level blocker is present but its reason is neither of the two
254:     // Phase 8 recognizes. This is unknown/future evidence -- fail closed
255:     // immediately rather than fall through to round-based classification,
256:     // which was never meant to explain an unrecognized top-level blocker.
257:     const evidence = baseEvidence(repairOutcome, {
258:       top_level_blocker: Object.freeze({ reason: topBlocker?.reason ?? null, detail: topBlocker?.detail ?? null }),
259:     });
260:     return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', evidence, 'supervisor_review');
261:   }
262: 
263:   const lastRound = repairOutcome.rounds[repairOutcome.rounds.length - 1] ?? null;
264:   if (!lastRound) {
265:     // Escalated with no round evidence and no top-level blocker at all --
266:     // nothing to classify against. Fail closed rather than guess.
267:     return buildGateResult('NEEDS_REVIEW', 'unrecognized_repair_outcome', baseEvidence(repairOutcome), 'supervisor_review');
268:   }
269: 
270:   if (lastRound.kind === 'execution') return classifyExecutionRound(repairOutcome, lastRound);
271:   if (lastRound.kind === 'validation') return classifyValidationRound(repairOutcome, lastRound);
272: 
273:   // Unrecognized round.kind value. Fail closed.
274:   return buildGateResult(
275:     'NEEDS_REVIEW',
276:     'unrecognized_repair_outcome',
277:     baseEvidence(repairOutcome, { last_round_kind: lastRound.kind ?? null }),
278:     'supervisor_review',
279:   );
280: }
